DWORD __stdcall TXT_Experience_GetExpRatio(int32_t nLevel) {
    if (!sgtDataTable.pTxtExperience) {
      return 0;
    }
    if (nLevel < 1) {
      return sgtDataTable.pTxtExperience->ExpRatio;
    }
    if (nLevel > sgtDataTable.pTxtExperience->Class[0]) {
      return 0;
    }

    return sgtDataTable.pTxtExperience[nLevel + 1].ExpRatio;
}

// @sourcefile .\DATATBLS\DataTbls.cpp
void __fastcall TXT_SaveTableToBinFile(D2PoolManagerStrc * pMemory, char * szTableName, D2ArchiveStrc * * ppInput, size_t * pSize2, size_t * pSize1) {
    FILE* pFile;
    size_t nLoadedSize;
    char szFilePath[260];
    uint32_t dwStackCookie = DEFAULT_SECURITY_COOKIE ^ (uintptr_t)0;
    if (sgtDataTable.bUseTxt && *ppInput) {
      /* LPCSTR param_2 for wsprintfA */ /* LPSTR param_1 for wsprintfA */ wsprintfA(szFilePath, "%s\\%s.bin", "DATA\\GLOBAL\\EXCEL", szTableName);
      pFile = fopen(szFilePath, "wb");
      if (pFile) {
        fwrite(*ppInput, *pSize2, 1, pFile);
        fclose(pFile);
      }

      D2_FREE_POOL(nullptr, *ppInput);
    }

    D2ArchiveStrc* pLoadedArchive = ARCHIVE_LoadDataTables(pMemory, szTableName, ".bin", &nLoadedSize, ".\\DATATBLS\\DataTbls.cpp", 0x27a);
    *ppInput = pLoadedArchive;
    *pSize1 = nLoadedSize;
    *pSize2 = nLoadedSize;
    Fog::Debug::GuardStack();
}

